function bhc_v418_image($src,$dst){$im=imagecreatefrompng($src);if(!$im)return false;$w=imagesx($im);$h=imagesy($im);$seen=array_fill(0,$w*$h,false);$q=new SplQueue();$push=function($x,$y)use(&$q,&$seen,$w,$h){if($x<0||$y<0||$x>=$w||$y>=$h)return;$i=$y*$w+$x;if(!$seen[$i]){$seen[$i]=true;$q->enqueue([$x,$y]);}};for($x=0;$x<$w;$x+=2){$push($x,0);$push($x,$h-1);}for($y=0;$y<$h;$y+=2){$push(0,$y);$push($w-1,$y);}$ns=[[1,0],[-1,0],[0,1],[0,-1]];while(!$q->isEmpty()){[$x,$y]=$q->dequeue();$c=imagecolorat($im,$x,$y);$br=($c>>16)&255;$bg=($c>>8)&255;$bb=$c&255;foreach($ns as [$dx,$dy]){$nx=$x+$dx;$ny=$y+$dy;if($nx<0||$ny<0||$nx>=$w||$ny>=$h)continue;$i=$ny*$w+$nx;if($seen[$i])continue;$n=imagecolorat($im,$nx,$ny);$r=($n>>16)&255;$g=($n>>8)&255;$b=$n&255;if(max(abs($r-$br),abs($g-$bg),abs($b-$bb))<=22&&max($r,$g,$b)-min($r,$g,$b)<=28){$seen[$i]=true;$q->enqueue([$nx,$ny]);}}}$cut=imagecreatetruecolor($w,$h);imagealphablending($cut,false);imagesavealpha($cut,true);$clear=imagecolorallocatealpha($cut,255,255,255,127);imagefilledrectangle($cut,0,0,$w,$h,$clear);for($y=0;$y<$h;$y++)for($x=0;$x<$w;$x++){if($seen[$y*$w+$x])continue;$c=imagecolorat($im,$x,$y);imagesetpixel($cut,$x,$y,imagecolorallocatealpha($cut,($c>>16)&255,($c>>8)&255,$c&255,0));}$ow=4096;$oh=(int)round($h*4096/$w);$out=imagecreatetruecolor($ow,$oh);imagealphablending($out,false);imagesavealpha($out,true);imagefilledrectangle($out,0,0,$ow,$oh,$clear);imagecopyresampled($out,$cut,0,0,0,0,$ow,$oh,$w,$h);imagepng($out,$dst,6);imagedestroy($im);imagedestroy($cut);imagedestroy($out);return true;}
